#!/usr/bin/env node
// Clean Yield MCP server (stdio, JSON-RPC 2.0, one message per line). No dependencies.
//
// - initialize / tools/list / ping work WITHOUT any key: tools/list always returns the
//   five Clean Yield tools from tools.json (generated by scripts/build-tools.mjs from the
//   public Apify API: current Store price + published input schema of each Actor).
// - tools/call without APIFY_TOKEN returns a clear isError result explaining how to get one.
// - tools/call with APIFY_TOKEN is delegated to Apify's official MCP server
//   (@apify/actors-mcp-server, MIT), started on first use with --tools limited to these
//   five Actors; its result is returned unchanged. Your token goes only to Apify.
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { createInterface } from 'node:readline';

const pkg = JSON.parse(readFileSync(new URL('./package.json', import.meta.url), 'utf8'));
const { tools: CATALOG } = JSON.parse(readFileSync(new URL('./tools.json', import.meta.url), 'utf8'));
const TOOLS = CATALOG.map(({ name, title, description, inputSchema, annotations }) => ({ name, title, description, inputSchema, annotations }));
const BY_NAME = new Map(CATALOG.map((t) => [t.name, t]));

const OFFICIAL_PKG = '@apify/actors-mcp-server@0.20.2';
const SUPPORTED_PROTOCOLS = ['2025-11-25', '2025-06-18', '2025-03-26', '2024-11-05'];
const CHILD_PROTOCOL = '2025-06-18';

const NO_TOKEN_TEXT = [
    'APIFY_TOKEN is not set, so this tool cannot run yet. Listing tools works without a key; running one needs your own Apify API token.',
    'How to get it (about 1 minute): create a free account at https://console.apify.com/sign-up (the free plan includes USD 5 of usage every month, enough to try every tool),',
    'then copy your token from Apify Console > Settings > API & Integrations (https://console.apify.com/settings/integrations).',
    'Add it to this server\'s environment in your MCP client config, e.g. "env": { "APIFY_TOKEN": "<your token>" }, and restart the client.',
    'Each tool charges per valid result on your own Apify account; failed or not-found inputs are free.',
].join('\n');

const log = (...a) => console.error('clean-yield-mcp:', ...a);
const send = (msg) => process.stdout.write(`${JSON.stringify(msg)}\n`);
const reply = (id, result) => ({ jsonrpc: '2.0', id, result });
const fail = (id, code, message) => ({ jsonrpc: '2.0', id, error: { code, message } });
const toolError = (text) => ({ content: [{ type: 'text', text }], isError: true });

// ---------- delegation to the official Apify MCP server ----------
let child = null; // { proc, pending: Map, nextId, ready: Promise, nameMap: Map }
const clientRequestToChild = new Map(); // our client's request id -> child request id (for cancellation)
let inFlight = 0;

function startChild() {
    const bin = process.env.APIFY_MCP_BIN;
    const actors = CATALOG.map((t) => t.actor).join(',');
    const [cmd, args] = bin ? [bin, ['--tools', actors]] : ['npx', ['-y', OFFICIAL_PKG, '--tools', actors]];
    const proc = spawn(cmd, args, { stdio: ['pipe', 'pipe', 'inherit'], env: process.env, shell: process.platform === 'win32' });
    const c = { proc, pending: new Map(), nextId: 1, nameMap: new Map() };
    const request = (method, params) => new Promise((resolve, reject) => {
        const id = c.nextId++;
        c.pending.set(id, { resolve, reject });
        proc.stdin.write(`${JSON.stringify({ jsonrpc: '2.0', id, method, params })}\n`);
        c.lastId = id;
    });
    c.request = request;
    createInterface({ input: proc.stdout }).on('line', (line) => {
        if (!line.trim().startsWith('{')) return; // ignore non-JSON noise (e.g. npx)
        let msg;
        try { msg = JSON.parse(line); } catch { return; }
        if (msg.id !== undefined && msg.method === undefined) { // response
            const p = c.pending.get(msg.id);
            if (p) { c.pending.delete(msg.id); p.resolve(msg); }
        } else if (msg.method && msg.id !== undefined) { // child -> client request: not supported
            proc.stdin.write(`${JSON.stringify(fail(msg.id, -32601, 'Not supported by clean-yield-mcp'))}\n`);
        } else if (msg.method === 'notifications/progress' || msg.method === 'notifications/message') {
            send(msg); // progress tokens are passed through unchanged
        }
    });
    const onGone = (why) => {
        for (const p of c.pending.values()) p.reject(new Error(why));
        c.pending.clear();
        if (child === c) child = null;
    };
    proc.on('error', (e) => onGone(`could not start the Apify MCP server (${e.message})`));
    proc.on('exit', (code) => onGone(`the Apify MCP server exited (code ${code})`));
    proc.stdin.on('error', () => {});
    c.ready = (async () => {
        const init = await request('initialize', { protocolVersion: CHILD_PROTOCOL, capabilities: {}, clientInfo: { name: pkg.name, version: pkg.version } });
        if (init.error) throw new Error(`Apify MCP server initialize failed: ${init.error.message}`);
        proc.stdin.write(`${JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' })}\n`);
        const list = await request('tools/list', {});
        if (list.error) throw new Error(`Apify MCP server tools/list failed: ${list.error.message}`);
        for (const ours of CATALOG) {
            const [owner, name] = ours.actor.split('/');
            const theirs = list.result.tools.find((t) => t.name === `${owner}--${name}` || t.title === ours.actor)
                ?? list.result.tools.find((t) => (t.description || '').includes(`"${ours.actor}"`));
            if (theirs) c.nameMap.set(ours.name, theirs.name);
        }
        log(`Apify MCP server ready (${c.nameMap.size}/${CATALOG.length} tools mapped)`);
    })();
    c.ready.catch(() => { try { proc.kill(); } catch {} });
    return c;
}

async function callTool(id, params) {
    const ours = BY_NAME.get(params?.name);
    if (!ours) return fail(id, -32602, `Unknown tool: ${params?.name}. Available: ${TOOLS.map((t) => t.name).join(', ')}`);
    if (!process.env.APIFY_TOKEN) return reply(id, toolError(NO_TOKEN_TEXT));
    try {
        if (!child) child = startChild();
        const c = child;
        await c.ready;
        const target = c.nameMap.get(ours.name);
        if (!target) return reply(id, toolError(`The Apify MCP server did not expose ${ours.actor}. Check that your APIFY_TOKEN is valid.`));
        const p = c.request('tools/call', { ...params, name: target, arguments: params.arguments ?? {} });
        clientRequestToChild.set(id, { c, childId: c.lastId });
        const res = await p;
        clientRequestToChild.delete(id);
        if (res.error) return { jsonrpc: '2.0', id, error: res.error };
        return reply(id, await appendItems(c, res.result));
    } catch (e) {
        clientRequestToChild.delete(id);
        return reply(id, toolError(`Could not run ${ours.actor}: ${e.message}`));
    }
}

// The official server's Actor tools return the run summary and point to its separate
// get-dataset-items tool. This server exposes only the five Actor tools, so it fetches the
// rows itself through that same official server (same token) and appends them as one more
// content block. The official result is kept unchanged.
const MAX_ITEMS = Math.max(1, Number(process.env.CLEAN_YIELD_MAX_ITEMS) || 100);
async function appendItems(c, result) {
    const ds = result?.structuredContent?.storages?.datasets?.default;
    if (!ds?.id || !ds.itemCount || result.isError) return result;
    const limit = Math.min(ds.itemCount, MAX_ITEMS);
    try {
        const res = await c.request('tools/call', { name: 'get-dataset-items', arguments: { datasetId: ds.id, limit, clean: true } });
        const blocks = res.result?.content?.filter((b) => b.type === 'text') ?? [];
        if (res.error || res.result?.isError || !blocks.length) throw new Error(res.error?.message || blocks[0]?.text || 'no items returned');
        const note = { type: 'text', text: `Results (${limit} of ${ds.itemCount} items from dataset ${ds.id}${ds.itemCount > limit ? `; the rest stay in that dataset on your Apify account, raise CLEAN_YIELD_MAX_ITEMS to return more` : ''}):` };
        return { ...result, content: [...(result.content || []), note, ...blocks] };
    } catch (e) {
        return { ...result, content: [...(result.content || []), { type: 'text', text: `The run finished but its items could not be fetched here (${e.message}). They are in dataset ${ds.id} on your Apify account.` }] };
    }
}

// ---------- our own MCP server ----------
async function handle(msg) {
    if (!msg || msg.jsonrpc !== '2.0' || typeof msg.method !== 'string') {
        return msg && msg.id !== undefined && msg.method === undefined ? null : fail(msg?.id ?? null, -32600, 'Invalid Request');
    }
    const { id, method, params } = msg;
    const isNotification = id === undefined;
    switch (method) {
        case 'initialize': {
            const requested = params?.protocolVersion;
            return reply(id, {
                protocolVersion: SUPPORTED_PROTOCOLS.includes(requested) ? requested : CHILD_PROTOCOL,
                capabilities: { tools: { listChanged: false } },
                serverInfo: { name: 'clean-yield', title: 'Clean Yield Data Tools', version: pkg.version },
                instructions: 'Five data tools (live company jobs, company enrichment from a website, App Store & Google Play reviews, FMCSA US carriers, Latin American public tenders). Listing is free; running a tool needs APIFY_TOKEN and is billed per valid result on the user\'s Apify account.',
            });
        }
        case 'notifications/initialized':
            return null;
        case 'notifications/cancelled': {
            const m = clientRequestToChild.get(params?.requestId);
            if (m) m.c.proc.stdin.write(`${JSON.stringify({ jsonrpc: '2.0', method: 'notifications/cancelled', params: { ...params, requestId: m.childId } })}\n`);
            return null;
        }
        case 'ping':
            return reply(id, {});
        case 'tools/list':
            return reply(id, { tools: TOOLS });
        case 'tools/call':
            inFlight++;
            try { return await callTool(id, params); } finally { inFlight--; }
        case 'resources/list':
            return reply(id, { resources: [] });
        case 'prompts/list':
            return reply(id, { prompts: [] });
        default:
            return isNotification ? null : fail(id, -32601, `Method not found: ${method}`);
    }
}

async function onLine(line) {
    if (!line.trim()) return;
    let msg;
    try { msg = JSON.parse(line); } catch { send(fail(null, -32700, 'Parse error')); return; }
    if (Array.isArray(msg)) {
        const out = (await Promise.all(msg.map(handle))).filter(Boolean);
        if (out.length) send(out);
        return;
    }
    const out = await handle(msg);
    if (out) send(out);
}

const rl = createInterface({ input: process.stdin });
rl.on('line', (line) => { onLine(line).catch((e) => log(e.stack || e)); });
rl.on('close', () => {
    // stdin closed: let in-flight calls finish, then stop the child. No process.exit():
    // it can cut off stdout still being written to a pipe; node exits once output is flushed.
    const done = () => { if (child) child.proc.kill(); };
    const wait = () => (inFlight ? setTimeout(wait, 200) : done());
    wait();
});
for (const sig of ['SIGINT', 'SIGTERM']) process.on(sig, () => { if (child) child.proc.kill(sig); process.exit(0); });
